INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(1100, 0, 11, 0, 0, 0, 'Wetlands', 'The Wetlands are a vast, cold marsh lying between the mountains of Khaz Modan and the sea, cloaked in mist beneath a sky that rarely clears. This was once dwarven country, dotted with Ironforge strongholds and overlooked by Grim Batol, the old seat of the Wildhammer clan, but war after war has reduced most of those holds to rubble. Today the Alliance clings to the coast at Menethil Harbor, a port raised after the Second War and named for King Terenas Menethil II. Inland, nothing is secure. Remnants of the Dragonmaw orcs have crept out of the eastern hills to threaten the harbor and choke the pass at Dun Algaz. Dark Iron dwarves have wrecked one of the two bridges of the Thandol Span and seized Dun Modr. Red dragons guard the sealed gates of Grim Batol, while gnolls, murlocs, raptors and stranger things of the bog roam the fens between.', 'warcraft.wiki.gg/wiki/Wetlands_(Classic) (vast cold swamp, mists, ruined Ironforge strongholds, Wildhammer control, Menethil Harbor named for Terenas); warcraft.wiki.gg/wiki/Menethil_Harbor (rebuilt after the Second War); quest 455 description; quest 464 description; quest 303 description; quest 633 description (remaining bridge); warcraft.wiki.gg/wiki/Thandol_Span (one of the two bridges all but destroyed)'),
(1101, 1, 11, 1, 0, 0, 'Menethil Harbor', 'Menethil Harbor sits on the western shore of the Wetlands, the Alliance''s only stronghold in this dreary region. Orgrim Doomhammer first chose these waters as the place to build the Horde''s invasion fleet; after the Second War the site was rebuilt as an Alliance port under Grand Admiral Daelin Proudmoore and named in honor of King Terenas Menethil II. Its stone keep, where Captain Stoutfist keeps his war room, watches over a town of merchants, tanners and sailors, and the Deepwater Tavern is never short of a pint or a tale. Ships sail from its docks to Theramore across the sea and north to Valgarde in Northrend, and the crocolisk hides cured here are shipped to ports around the world.', 'warcraft.wiki.gg/wiki/Menethil_Harbor (Doomhammer''s fleet site, rebuilt under Daelin Proudmoore, named for Terenas); warcraft.wiki.gg/wiki/Wetlands_(Classic) (the Alliance''s only presence in this dreary region); quest 473 description (Stoutfist in the keep''s war room); quest 942 description (Deepwater Tavern); quest 484 description (cured crocolisk skins shipped to ports around the world); transports table: Lady Mehley to Theramore, Northspear to Valgarde; npc_text 823 (Innkeeper Helbrek: stories to tell and kegs to empty)'),
(1102, 1, 11, 2, 0, 0, 'Menethil Bay', 'South of the harbor, the shallows of Menethil Bay hide the wreck of the Flying Osprey, an elven destroyer that sailed with the Kul Tiras Third Fleet for protection while carrying a cargo of Lightforge Iron, a metal prized because weapons forged from it strike with holy truth. The dragons that sank the fleet did not spare her either. Her waterlogged chest has since been clawed open by murlocs, and the Bluegill raiders who prowl the bay carry off the precious ingots they found inside. Crocolisks bask along the muddy shore, and stranglekelp and iron coral grow thick beneath the water.', 'quest 321 description and reward text (Flying Osprey, elvish destroyer, Lightforge Iron, wrecked south of Menethil, murloc claw marks); quest 270 description (items crafted from it strike with holy truth); quests 324, 526 (murloc raiders near the wreck carry the ingots); zone_areas: Waterlogged Chest 2734, Bluegill Raider x11, Wetlands Crocolisks, Stranglekelp and Iron Coral in area 299'),
(1103, 1, 11, 3, 0, 0, 'Baradin Bay', 'Baradin Bay is the wide grey water washing the western coast of the Wetlands, with Menethil Harbor set upon its shore. Long before the harbor existed, Orgrim Doomhammer chose a small island in this bay as the place to build the fleet the Horde would turn against the Alliance in the Second War. Today the shallows are thick with stranglekelp and giant clams, Bluegill murlocs raid along the beaches, and the giant crocolisks of the northern coast are so dangerous that the town tanner''s own apprentice lost a leg trying to skin them.', 'warcraft.wiki.gg/wiki/Wetlands (Doomhammer chose a small island in Baradin Bay for his invasion fleet); warcraft.wiki.gg/wiki/Wetlands_(Classic) (Menethil Harbor sits in Baradin Bay); quest 471 description and request text (giant crocs north up the coast; apprentice left with one leg); zone_areas: Stranglekelp, Giant Clam, Bluegill murlocs and Giant Wetlands Crocolisk in area 298'),
(1104, 1, 11, 4, 0, 0, 'Bluegill Marsh', 'North of Menethil Harbor, Bluegill Marsh is a muddy stretch of coast where murlocs have crawled up out of the deep water to build their hovels. The Bluegill tribe harasses fishers and merchants along the road, and the boldest of them, a murloc called Gobbler, harries merchants on the coast road before slipping back to the safety of the huts by the river inlet. When the merchant ship Blind Princess was raided, much of her cargo was dragged overboard and scattered through these hovels, among it a valuable silver statuette of Terenas Menethil, shown as a young, long-haired paladin with his hammer raised.', 'quest 279 description (murlocs building villages, Gobbler harries merchants, river inlet); quest 281 description (Blind Princess raided, Menethil Statuette); quest 286 description (silvery figurine of a young long-haired paladin with hammer upraised); DB: Gobbler 1259 spawn in area 1022; Bluegill murlocs, Battered Footlockers, Half-buried Barrel and Damaged Crate in area 1022'),
(1105, 1, 11, 5, 0, 0, 'The Lost Fleet', 'Off the northern coast lie the wrecks of the Kul Tiras Third Fleet, sent to the bottom during the Second War when red dragons ridden by Dragonmaw orcs fell upon it with fire. The fleet does not rest. A cursed treasure locked in the strongbox of the Intrepid, a corrupted Eye of Paleth, binds the souls of the drowned crew to the rotting hulls, and cursed sailors and marines still shamble across the broken decks hungry for the living. Captain Halyndor, whom his surviving first mate blames for leading them all to their doom, walks the Intrepid still with the strongbox key.', 'quest 288 description (attacked by red dragons controlled by orcs); quest 289 description (souls trapped in the hulls, wrecked off the coast to the north); quest 290 description (strongbox on the Intrepid, Captain Halyndor holds the key); quest 292 description (Cursed Eye of Paleth); quest 321 description (sunk by red dragons during the last Great War); creature_text 1239 (Curse you, Halyndor! You led us to our doom!); creature_text 1157/1158 (Brains..., Time to join us); warcraft.wiki.gg/wiki/The_Lost_Fleet (Third Fleet, Intrepid, Second War); DB: Captain Halyndor 1160, Cursed Sailor/Marine and Intrepid''s Locked Strongbox in area 1039'),
(1106, 1, 11, 6, 0, 0, 'Saltspray Glen', 'Saltspray Glen lies in the far northwest of the Wetlands, between Bluegill Marsh and the open waters of Baradin Bay. It takes its name from the sea: when a strong wind blows in off the bay, the waves fling salt water far across the grass. Raptors hunt its slopes and crocolisks wallow in its streams, but its most troubling inhabitants are the fen creepers, risen bog creatures that the Greenwarden counts among the fevered blisters on his land, and the larger fen lords that walk with them.', 'warcraft.wiki.gg/wiki/Saltspray_Glen (location, name from seawater thrown inland, raptors); quest 275 description (Fen Creepers have risen, diseased blisters on the land); zone_areas: Highland Lashtail/Scytheclaw/Razormaw, Wetlands Crocolisk, Fen Creeper and Fen Lord in area 1023; warcraft.wiki.gg/wiki/Saltspray_Glen (bordered by Bluegill Marsh to the south, Baradin Bay to the north and west)'),
(1107, 1, 11, 7, 0, 0, 'Sundown Marsh', 'Sundown Marsh spreads across the north of the Wetlands, a broad fen of reeds and standing water. It is Mosshide country. Gnoll trappers, brutes and mystics roam its pools under their alphas, and a notorious Mosshide named Gnawbone prowls among them. A wandering bog creature called Mirelow rises from the muck, and crocolisks lurk in every channel. Even so, trade goes on: by an old mill near the road, a pair of dwarven and gnomish merchants sell engineering parts and special goods to Alliance travellers on the road.', 'zone_areas: Mosshide Trapper/Brute/Mystic/Alpha, Gnawbone 14425, Mirelow 14424, crocolisks, Wenna Silkbeard 2679 and Fradd Swiftgear 2682 in area 1024; warcraft.wiki.gg/wiki/Fradd_Swiftgear (pre-Cataclysm: located by a mill in Sundown Marsh); creature_template subnames 2679 Special Goods Dealer, 2682 Engineering Supplies; creature_template 2679 faction 55, 2682 faction 875 (Alliance factions)'),
(1108, 1, 11, 8, 0, 0, 'Ironbeard''s Tomb', 'Just west of the road to Dun Modr stands Ironbeard''s Tomb, an ancient dwarven crypt beside a small graveyard, watched over by a statue presumed to be Ironbeard himself. It has become a sorry place. Oozes of black, crimson and monstrous kinds have seeped into the crypt and defiled it, and those who would bury their dead no longer come here. Sida of Menethil Harbor still made her weekly visit until the oozes set upon her; in her panic she flung her bag at one, and the creature simply swallowed it.', 'warcraft.wiki.gg/wiki/Ironbeard''s_Tomb (crypt west of the Dun Modr road, graveyard, statue presumably of Ironbeard, defiled by black, crimson and monstrous oozes, no one buries their dead there); quest 470 description (Sida''s weekly visit, bag swallowed by an ooze); zone_areas: Black Ooze, Crimson Ooze, Monstrous Ooze in area 309'),
(1109, 1, 11, 9, 0, 0, 'Dun Modr', 'Dun Modr is an old dwarven town in the north of the Wetlands, standing just south of the Thandol Span and long a strategic key to the whole region. While Ironforge''s soldiers fought for the Alliance in distant lands, the Dark Iron dwarves struck at home: they laid waste to the Span, then fell upon Dun Modr before its regiment could regroup. Most of the defenders were killed and Longbraid the Grim sounded the retreat. His survivors now hold a small camp outside the walls, waiting on reserves that never seem to come, while Dark Iron tunnelers, saboteurs and demolitionists swarm through the town.', 'warcraft.wiki.gg/wiki/Dun_Modr (just south of the Span, major strategic point, Dark Iron attack); quest 303 description and request text (soldiers abroad, Span laid waste, Dun Modr fell, reserve); quest 472 description (most of the regiment killed, Longbraid sounded the retreat); quest 634 description (awaiting the reserves of Ironforge); zone_areas: Longbraid 1071, Motley 1074, Rhag 1075, Roggo 1072, Ashlan 1073 and Dark Iron Dwarf/Tunneler/Saboteur/Demolitionist in area 205'),
(1110, 1, 11, 10, 0, 0, 'Thandol Span', 'The Thandol Span was raised by the dwarves of Ironforge after the War of the Three Hammers, two arches joining Khaz Modan to the lands of Lordaeron so that trade and kinship with the Wildhammers of Aerie Peak might endure. Now it lies half in ruin. In an attack planned by Kam Deepfury and Balgaras the Foul, the Dark Irons blew apart the west bridge and killed many of its defenders, among them Longbraid''s brother and a soldier named Sully Balloo, whom King Magni has ordered honored with a memorial. The dwarves cling to the remaining bridge, their main northern supply line. Near it wanders Comar Villard, a grieving man still searching for some sign of his lost wife.', 'warcraft.wiki.gg/wiki/Thandol_Span (built after the War of the Three Hammers, two arches, Khaz Modan to Lordaeron, Wildhammer ties); quest 304 description (West Bridge destroyed, Longbraid''s brother); quest 633 description (Kam Deepfury mastermind, remaining bridge, major supply line to the north); quest 378 description (Deepfury conspirator); quest 689 description (King''s memorial for Sully Balloo, died in the Thandol Span tragedy); quest 1476 description (Comar Villard wandering the Wetlands for a sign of his wife); DB: Comar Villard 5683 and Ebenezer Rustlocke''s Corpse 2652 in area 881'),
(1111, 1, 11, 11, 0, 0, 'Direforge Hill', 'Southeast of Dun Modr rises Direforge Hill, where the Dark Iron invaders have made their camp. From here their leader, the warlock Balgaras the Foul, directs the war on the Wetlands, sending tunnelers, saboteurs and demolitionists to do his fighting while he keeps to the safety of the hill. The survivors of Dun Modr despise him as a coward and have long tried to run him down. Raptors stalk the surrounding slopes, oozes creep through the gullies, and crimson and flamesnorting whelps flit among the rocks.', 'quest 304 description (Balgaras hides in his camp on Direforge Hill to the southeast, sends his soldiers, coward); quest 304 request text (he has been evading us); zone_areas: Balgaras the Foul 1364, Dark Iron Dwarf/Tunneler/Saboteur/Demolitionist, Highland raptors, oozes and Crimson/Flamesnorting/Lost Whelps in area 1016'),
(1112, 1, 11, 12, 0, 0, 'The Green Belt', 'The Green Belt is the marshy lowland east of the road where it forks toward Dun Modr, a tangle of fen and reed thick with crocolisks, oozes and young red whelps. Here, among the crocs, dwells the creature the folk of Menethil call the Greenwarden, a great bog beast who answers to the name Rethiel. An old sailor in the harbor warns that it is a monster that will bite a traveller in half, but those who seek it out find a guardian grieving for a land that weeps from festering wounds.', 'quest 463 description (marsh east of the road where it forks to Dun Modr, lurking among the crocs, bites you in half); quest 463 reward text (many names, answers to Rethiel, lands weep from festered wounds); warcraft.wiki.gg/wiki/Rethiel_the_Greenwarden (bog beast); zone_areas: Rethiel 1244, Young Wetlands Crocolisk, oozes and red whelps in area 1025'),
(1113, 1, 11, 13, 0, 0, 'Whelgar''s Excavation Site', 'East of Menethil Harbor, the Explorers'' League dug into the marsh under Prospector Whelgar, with soldiers sent by Longbraid to watch over them. The dig turned up rare artifacts, great bones and the Goaz Stone, a tablet in Titan script whose broken text spoke of a divine plan and a doomed prophecy. Then the mottled raptors came. The pack overran the site and killed many of the dwarves, and only Whelgar, Merrin Rockweaver and Ormer Ironbraid, who held off the beasts while the others fled, escaped to a ridge above the dig. There they remain trapped, while fragments of the stone lie scattered among the ruined diggings below.', 'quest 306 description (rare artifacts, large bones, raptors overwhelmed the site, Ormer defended them, trapped); quest 294 description (bones attracted the raptors, brethren killed); quest 299 description (Goaz Stone, divine plan, doomed prophecy, fragments in artifacts and loose soil); quest 299 reward text (Titan script); warcraft.wiki.gg/wiki/Longbraid_the_Grim (sent soldiers to accompany Whelgar); warcraft.wiki.gg/wiki/Whelgar''s_Excavation_Site (east of Menethil, ridge overlooking the dig); zone_areas: Whelgar 1077, Merrin 1076, Ormer 1078, Ancient Relic and Loose Soil objects in area 118; page_text 93-94 (Merrin''s Letter: battalion from Longbraid''s regiment, only 3 survived)'),
(1114, 1, 11, 14, 0, 0, 'Angerfang Encampment', 'In the hills east of Whelgar''s Excavation lies the Angerfang Encampment, stronghold of the Dragonmaw orcs in the Wetlands. When their red dragon slaves broke free at the end of the Second War, the clan was all but destroyed, and the few survivors fled Grim Batol into these mountains. Here they have slowly regained their strength under Chieftain Nek''rosh. Raiders, swamprunners, bonewarders and shadowwarders crowd the camp beneath its war banners, and Nek''rosh has had catapults built here, meant to lay siege to Menethil Harbor itself.', 'quest 464 description (Dragonmaws all but destroyed, fled Grim Batol into the mountains east of Whelgar''s Excavation, encampment northeast of Menethil, war banners); quest 465 description (catapults to lay siege to Menethil, in the Dragonmaw encampment); warcraft.wiki.gg/wiki/Nek''rosh (based at the Angerfang Encampment); zone_areas: Chieftain Nek''rosh 2091, Dragonmaw Raider/Swamprunner/Bonewarder/Shadowwarder/Centurion, Dragonmaw Catapult 1609 in area 1036'),
(1115, 1, 11, 15, 0, 0, 'Grim Batol', 'In the eastern mountains stands Grim Batol, where Thane Khardros founded the kingdom of the Wildhammer clan. When the Dark Irons made war on their kin, Modgud, wife of the sorcerer-thane Thaurissan, led the assault on it and laid a curse of shadow upon it, and though Khardros slew her, the Wildhammers found their home tainted and left. In the Second War the Dragonmaw clan under the warlock Nekros made it their stronghold, using the Demon Soul to hold the Dragonqueen Alexstrasza captive, until Rhonin and his companions destroyed the artifact. The freed red dragons tore Grim Batol apart in their fury. Now its gates are sealed, and red dragonkin, among them the lieutenant Axtroz, guard them against all comers.', 'warcraft.wiki.gg/wiki/Grim_Batol (Khardros, Modgud''s curse, uninhabitable, Dragonmaw occupation, sealed and guarded by red dragonkin including Axtroz; pre-Cataclysm sections only); page_text 2019-2021 (The Battle of Grim Batol, book in Menethil Harbor: Nekros, Demon Soul, Alexstrasza, Rhonin, dragons tore Grim Batol apart); quest 6585 description (the Red Flight now guards Grim Batol, their lieutenant Axtroz); zone_areas: Axtroz 12899, Scalebane Royal Guard, Wyrmkin Firebrand, Red Scalebane, Red Dragonspawn in area 1038'),
(1116, 1, 11, 16, 0, 0, 'Mosshide Fen', 'Mosshide Fen lies in the south of the Wetlands, not far from the dwarven gate at Algaz, and it is the home ground of the Mosshide gnolls. For many years the Mosshides lived in these marshes peacefully enough, but their numbers have swollen. Their feet trample the fen''s bushes and flowers, and their axes take more wood than the land can spare to feed their fires, so that even the Greenwarden has turned against them. Gnolls, mongrels and fenrunners roam the pools with their mistweavers, sharing the fen with young crocolisks and black slimes.', 'quest 276 description (Mosshides lived peacefully many years, growing in numbers, stamp flat bushes and flowers, axes cut too much wood; hunt them to the south near the Dwarven gate of Algaz); quest 277 description; zone_areas: Mosshide Gnoll/Mongrel/Fenrunner/Mistweaver, Young Wetlands Crocolisk, Black Slime in area 1020'),
(1117, 1, 11, 17, 0, 0, 'Thelgen Rock', 'Thelgen Rock is a great cavern in the southern Wetlands, northwest of the Algaz Gate, that runs deep into the mountains. Spiders infest it, the leech stalkers, and a monstrous one known as the Leech Widow hunts in the marsh nearby. Yet the cave holds a prize. Veins of incendicite run through its rock, a rare ore so volatile it is hard to work without blowing oneself up, which one dwarven pilot of Dun Morogh hopes, smelted the right way, could make cannon shells that pack a mighty punch.', 'warcraft.wiki.gg/wiki/Thelgen_Rock (cavern deep into the mountains, spiders, incendicite); quest 466 description (incendicite in a cave northwest of Algaz Gate, volatile, cannon shells; given by Pilot Stonegear 1377, QuestSortID 1 Dun Morogh); zone_areas: Leech Stalker 1111 x22 in area 1021; Leech Widow 1112 spawn at -3780,-2344 (area 11, just outside); creature_template 1111/1112 family 3 (spider)'),
(1118, 1, 11, 18, 0, 0, 'The Northern Algaz Road', 'North of the dwarven gate, the pass of Dun Algaz winds down out of the mountains into the Wetlands, and its road runs on to the fork where travellers turn west for Menethil Harbor. This northern stretch is Dragonmaw ground now. Orc scouts and grunts who usually keep to their hills have come down in force to hold the road, roaring for the Dragonmaw at any who pass, and their warlord Ma''ruk Wyrmscale waits near the Wetlands end. Only a few Ironforge mountaineers patrol the southern approach. While the orcs hold the pass, no relief can reach Menethil by land, and why the clan surged into Algaz remains a mystery even to the harbor''s defenders.', 'quest 455 description and reward text (Menethil is through Dun Algaz, north along the road, then west at the fork; Dragonmaws normally hide in the hills; their surge into Algaz a mystery to Valstag Ironjaw); quest 465 description (fighting in Dun Algaz blocks reinforcements to Menethil); creature_text 2102/2103 (For the Dragonmaw!); zone_areas: Dragonmaw Scout x17, Grunt x16, Ma''ruk Wyrmscale 2090 <Dragonmaw Warlord> at -4207,-2377 (north end), patrolling Mountaineers Grugelm, Dokkin, Thar, Rharen near the southern end in area 836'),
(1119, 2, 11, 1, 1, 0, 'Captain Stoutfist', 'Captain Stoutfist commands the defense of Menethil Harbor from the war room inside its keep, and his position is an uneasy one. The Dragonmaw orcs have pushed into Dun Algaz, cutting the town off from reinforcements, and his men have learned that Chieftain Nek''rosh is building catapults to lay siege to the harbor itself. With no soldiers to spare, Stoutfist calls upon any capable volunteer, sending them to seize the war banners of the Angerfang camp, burn the catapults and bring back Nek''rosh''s head. He knows the clan''s history well and does not underestimate it: without their dragons the Dragonmaw are not the threat they once were, but they remain fierce foes.', 'quest 473 description (in the keep, in the war room); quests 464, 465, 474 (descriptions and reward texts); creature_template 2104 faction 55 (Ironforge)'),
(1120, 2, 11, 2, 1, 0, 'Longbraid the Grim', 'Longbraid the Grim led the dwarven regiment that guarded Dun Modr and the Thandol Span. When the Dark Irons struck, his own brother died as the west bridge over the Span was destroyed, and before the regiment could regroup Dun Modr was overrun. Longbraid sounded the retreat and sent the wounded Harlo Barnaby to safety on the only surviving horse. Now he holds a camp outside the fallen town with what remains of his soldiers, hunting the warlock Balgaras and waiting on reserves from Ironforge. When his officers sent to the Alliance at Refuge Pointe for aid, the reply came back that Stromgarde had fallen and could spare no one: Longbraid is on his own.', 'quest 161 description (regiment guarding Dun Modr and the Thandol Span); quest 472 description and reward text; quest 304 description (brother died when the West Bridge was destroyed); quest 634 description and reward text (Captain Nials: he is on his own); warcraft.wiki.gg/wiki/Longbraid_the_Grim; creature_template 1071 faction 55'),
(1121, 2, 11, 3, 0, 0, 'Chieftain Nek''rosh', 'Nek''rosh is chieftain of the Dragonmaw clan in the Wetlands and son of Nekros Skullcrusher, the warlock who once held the red Dragonqueen captive in Grim Batol. When the magic that bound the dragons failed, they turned on their masters, slew Nekros and hunted the clan almost to extinction. Nek''rosh has sworn revenge on the dragons who killed his father. From the Angerfang Encampment he has rebuilt the clan''s strength while his warriors pushed into Dun Algaz, and he has raised catapults to besiege Menethil Harbor. He is seldom found without a guard of warriors about him.', 'quest 464 description and reward text (son of Nekros, magic failed, Nekros killed, vowed revenge); quest 465 description; warcraft.wiki.gg/wiki/Nek''rosh (Nek''rosh Skullcrusher, son of Nekros Skullcrusher, Angerfang, usually guarded by five orcs); page_text 2019 (Nekros held Alexstrasza in Grim Batol)'),
(1122, 2, 11, 4, 0, 0, 'Balgaras the Foul', 'Balgaras the Foul is the Dark Iron warlock who leads his clan''s invasion of the Wetlands. With Kam Deepfury he planned the attack on the Thandol Span, and under his command Dun Modr was taken. He calls himself a servant of Ragnaros, proclaims that the Dark Irons will reclaim their rightful lands, and promises to leave his foes nothing but ash and dust. To the dwarves of Ironforge he is a coward who sends his soldiers to do his bidding while he hides in his camp on Direforge Hill, and they hope his death would leave the remaining invaders easy to deal with.', 'creature_text 1364 (minions of Ragnaros, reclaim their rightful lands, ash and dust); quest 304 description and reward text; warcraft.wiki.gg/wiki/Thandol_Span (Kam Deepfury and Balgaras planned the attack); warcraft.wiki.gg/wiki/Dun_Modr (Dark Irons led by Balgaras)'),
(1123, 2, 11, 5, 1, 0, 'Rethiel the Greenwarden', 'Rethiel is a great bog beast of the Green Belt, known in Menethil Harbor as the Greenwarden and called a monster by an old sailor there. He says he has many names but answers to only a few. To Rethiel the Wetlands are a living thing, wounded and weeping: fen creepers have risen as fevered blisters on the land, and the Mosshide gnolls, once in balance, now trample the fens and burn living wood. He asks those the roots and ferns speak well of to heal these wounds, and casts the gnolls'' flints into the sea. His faith in the peoples of the Alliance has been tested before, but he allows that it may yet be restored.', 'quest 463 description and reward text; quests 275, 276, 277 (descriptions and reward texts); warcraft.wiki.gg/wiki/Rethiel_the_Greenwarden (bog beast, formerly Stormwind-affiliated); creature_template 1244 faction 12 (Stormwind)'),
(1124, 2, 11, 6, 1, 0, 'First Mate Fitzsimmons', 'Fitzsimmons was first mate of the Wave Mistress, a ship of the line in the Kul Tiras Third Fleet, and he is the only survivor of the dragonfire that sank the fleet off the Wetlands coast. He has washed up in Menethil Harbor, where he drinks away his days, begs for mead and, by his own cheerful admission, smells. He curses his old captain, Halyndor, for leading them all to their doom. Yet he has not forgotten his shipmates. In his dreams he hears their moans, their souls held in the wrecks by a cursed treasure, and he longs for someone brave enough to set them free.', 'quests 288, 289, 290 (descriptions and texts); creature_text 1239; quest 292 request text (Glorin calls him that drunk Fitzsimmons); creature_template 1239 faction 12'),
(1125, 2, 11, 7, 1, 0, 'Prospector Whelgar', 'Prospector Whelgar of the Explorers'' League led the dig that bears his name, east of Menethil Harbor. Just before mottled raptors overran the site he unearthed the Goaz Stone, a tablet in Titan script, and he has since been trapped on a ridge above the ruined dig with Merrin Rockweaver and their protector Ormer Ironbraid, too old, he admits, to brave the beasts below. Once the four lost fragments of the stone were recovered, his translation turned up words about the Old Gods, chained beneath the land, which he believes is the beginning of something epic. He also keeps a fossil that Archaeologist Flagongut is eager to study.', 'quest 299 description and reward text; quest 306 description; quest 943 description (Whelgar holds the original fossil); creature_text 1077 (I figured Flagongut would send someone for that fossil); creature_template 1077 subname Explorers'' League, faction 55'),
(1126, 2, 11, 8, 1, 0, 'Mikhail', 'Mikhail tends bar in Menethil Harbor, having left Stormwind a few years ago and settled here to retire. He still keeps friends in the capital, among them Elling Trias, and a visitor who comes in Elling''s name finds his hospitality multiplied tenfold. It was in the tavern where he works that the rogue Tapoke ''Slim'' Jahn was caught and confessed that he had sold out to the Defias, helping slip their agent aboard the King of Stormwind''s ship while it lay in the harbor, bound for Theramore. Mikhail confesses, though never where Elling might hear, that he misses the excitement of his old underground work.', 'quest 1248 description and reward text; quest 1249 description and reward text; quest 1250 description and reward text; creature_template 4963 faction 12; 4962 Tapoke Jahn spawned in area 150'),
(1127, 3, 11, 1, 1, 0, 'The Dragonmaw Threat', 'Word reached Loch Modan that the Dragonmaw orcs, who usually keep to their hills, had surged into Dun Algaz in force. If they held the pass, Loch Modan would be cut off from Menethil Harbor, so the mountaineers called for volunteers to break through. Those who reached Menethil found the orcs rising across the Wetlands. In the keep, Captain Stoutfist told the clan''s story: broken when their red dragons turned on them after the Second War, the survivors fled Grim Batol for the eastern hills and, under Nek''rosh, son of Nekros, had grown strong again. Stoutfist sent fighters to seize the war banners of the Angerfang Encampment, and their raid uncovered Nek''rosh''s plan: catapults to besiege Menethil while the fighting in Algaz held back any relief. The catapults were put to the torch and Nek''rosh was slain, a blow from which the clan may never recover.', 'quests 468, 455, 473, 464, 465, 474 (descriptions and reward texts)'),
(1128, 3, 11, 2, 1, 0, 'The Fall of Dun Modr', 'In Menethil Harbor a soldier named Harlo Barnaby woke with an axe wound in his back and terrible news: Dun Modr had fallen. The Dark Iron dwarves had struck the Thandol Span and then overrun the town before its regiment could regroup, and Harlo had been sent away on the only surviving horse. Searchers found his commander, Longbraid the Grim, alive outside the town with what remained of his soldiers. There Motley Garmason calls for pressure on the Dark Iron encampment while Roggo Harlbarrow tries in vain to reach the reserves, and Longbraid wants the cowardly warlock Balgaras the Foul slain in his camp on Direforge Hill. Vengeance reaches further still. Kam Deepfury, who plotted the attack on the Span, is held in the Stormwind Stockade for political reasons, and Motley will not let human bureaucracy stand between him and justice for Longbraid''s brother.', 'quests 472, 303, 304, 378 (descriptions, request and reward texts)'),
(1129, 3, 11, 3, 1, 0, 'The Thandol Span', 'After the explosion that tore through the Thandol Span, Longbraid sent Ol'' Ebenezer Rustlocke to scout the eastern bridge and see if it could be secured. Days passed with no word, and with Dun Modr under siege the dwarves had no one to spare to look for him. He was found dead near the Span, cut down in a Dark Iron ambush, a parchment clutched in his fist. It revealed that Kam Deepfury, the mastermind of the first attack, had arranged for a cache of explosives to be hidden across the Span in the Arathi Highlands, ready to bring down the last bridge and sever the dwarves'' main supply line to the north. The cache was destroyed in time. Rhag Garmason then begged the Alliance at Refuge Pointe for soldiers, but Captain Nials could spare none: Stromgarde itself had fallen, and her people were sworn to retake it first.', 'quests 631, 632, 633, 634 (descriptions and reward texts)'),
(1130, 3, 11, 4, 1, 0, 'The Doomed Fleet', 'The Third Fleet of Kul Tiras met its end off the Wetlands coast, burned and sunk by red dragons ridden by Dragonmaw orcs. Its lone survivor, First Mate Fitzsimmons, will tell the tale to anyone who buys him a drink: his drowned brothers still walk the wrecks, bound by a terrible thing hidden aboard the Intrepid. Freeing them means cutting down the cursed crew, taking the strongbox key from Captain Halyndor and opening the chest, where a blackened orb lies waiting, a Cursed Eye of Paleth. The dwarven priest Glorin Steelbrow cannot cleanse it, for the Eyes were crafted by human priests, and it must go to Archbishop Benedictus in Stormwind, who sees that it has witnessed a terrible tragedy. The same fleet once sheltered the elven ship Flying Osprey, and her lost Lightforge Iron still draws those seeking holy weapons to the bay.', 'quests 288, 289, 290, 292, 293 (descriptions and reward texts); quests 270, 321, 324, 526 (Lightforge Iron thread)'),
(1131, 3, 11, 5, 1, 0, 'The Whelgar Excavation', 'Tarrel Rockweaver of Menethil Harbor had a letter every week from his wife Merrin, who was digging with the Explorers'' League east of town, until two weeks passed in silence and a scout was sent to find her. Merrin''s news was grim. The team had begun uncovering great bones, the bones drew raptors, and the beasts overran the dig, killing many. Only Merrin, Prospector Whelgar and Ormer Ironbraid survived, trapped on a ridge above the site. Ormer swore vengeance on the raptors and on Sarltooth, the great beast he believes led them, while Whelgar sought the missing fragments of the Goaz Stone, whose Titan text speaks of Old Gods chained beneath the land. In Menethil, Archaeologist Flagongut had troubles of his own: raptors on the road had swallowed the Stone of Relu, the relic he needed to unlock the secrets of the fossil now in Whelgar''s keeping.', 'quests 305, 306 (descriptions and reward texts); quests 294, 295, 296; quest 299 description and reward text; quests 942, 943 (descriptions)'),
(1132, 3, 11, 6, 1, 0, 'The Greenwarden''s Charge', 'Ask about the Greenwarden in Menethil Harbor and an old sailor will call you a fool: the beast lurks among the crocs east of the Dun Modr road, they say, and bites travellers in half. Those who go anyway find Rethiel, a guardian of the fens who listens to the roots and ferns. The Wetlands, he says, weep from festering wounds. The Mosshide gnolls, peaceful for many years, have multiplied until they trample the marsh and cut down living trees for their fires, so he asks that their numbers be thinned and their crude flints taken, to be smashed and cast into the sea. Then the fevered fen creepers must be put down, so they can settle back into the marshes and the land''s fever can break. For this Rethiel grants a boon, and some of his strained faith in the peoples who share his land returns.', 'quests 463, 276, 277, 275 (descriptions and reward texts)');
